test("person tags scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "terms-C", "3");
  await ui.setSetting(pg_uma, "grace-days", "3");
  expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-03-13")).toBe(true);
  await ui.setSetting(pg_uma, "grace-C", "5");
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "0.40", "note": ""})).toBe(true);
  await ui.setSetting(pg_uma, "pot", "7.77");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00", "from": "2026-03-16", "to": "2026-03-25"})).toBe(true);
  expect(await ui.generatePeriods(pg_uma, "2026-02-01", "2026-04-30")).toBe(3);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "contact": "ADA@X", "tags": "b, a"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "terms": "20", "contact": "ben@x", "tags": "b, a"}));
  expect(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "contact": " Ada@x "})).toBeNull();
  expect(await ui.retire(pg_uma, p_ada, "2026-03-15")).toBe(true);
  await ui.showRetired(pg_uma, true);
  await ui.expectAuditView(pg_uma, "Ada", [
    `PERSON_RETIRED sheet=${sheet} by=uma name=Ada from=2026-03-15`,
    `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
    `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=B contact=ada@x`
  ]);
  expect(await ui.setSettingDated(pg_uma, "clerk-limit", "1.50", "2026-04-02", "3.00")).toBe(true);
  expect(await ui.periodAction(pg_uma, "2026-04", "close")).toBe(true);
  expect(await ui.bulkGrade(pg_uma, [p_cam, p_ada], {"grade": "B"})).toBe(2);
  expect(await ui.addClaim(pg_uma, p_cam, {"amount": "1.00", "date": "2026-03-15", "tags": " c "})).toBeNull();
  expect(await ui.statementAsOf(pg_uma, p_ada, "2026-03-15")).toBe(false);
  await ui.refresh(pg_uma);
  expect(await ui.periodAction(pg_uma, "2026-03", "close")).toBe(true);
  expect(await ui.editPerson(pg_uma, p_cam, {"grade": "A"})).toBe(true);
  expect(await ui.watch(pg_uma, p_ada, true)).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  await ui.showRetired(pg_vic, true);
  expect(await ui.transfer(pg_vic, p_ada, `${sheet}-t`)).toBe(false);
  expect(await ui.addClaim(pg_vic, p_cam, {"amount": "0.04", "date": "2026-02-25", "note": "n"})).toBeNull();
  expect(await ui.addClaimTwice(pg_vic, p_ada, {"amount": "99.95", "date": "2026-02-10"})).toBeNull();
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_ada)).toHaveCount(0);
  await ui.showRetired(pg_wes, true);
  expect(await ui.addClaim(pg_wes, p_ada, {"amount": "1.00", "note": "n", "ref": "R-1", "tags": " c "})).toBeNull();
  expect(await ui.addClaim(pg_wes, p_ada, {"amount": "25.00"})).toBeNull();
  await ui.setAsOf(pg_wes, "2026-03-09");
  await ui.refresh(pg_wes);
  await ui.expectAudit(sheet, [
    `ROLE_SET sheet=${sheet} by=uma user=vic role=steward`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=clerk-limit value=3.00`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=floor value=2.00`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=policy-date value=2026-03-05`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=period-numbering-from value=2026-03-01`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=terms-C value=3`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=grace-days value=3`,
    `HOLIDAY_ADDED sheet=${sheet} by=uma date=2026-03-24`,
    `HOLIDAY_ADDED sheet=${sheet} by=uma date=2026-03-13`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=grace-C value=5`,
    `TEMPLATE_SAVED sheet=${sheet} by=uma name=T1 amount=0.40 note=`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=pot value=7.77`,
    `RATE_SET sheet=${sheet} by=uma grade=A rate=5.00`,
    `RATE_SET sheet=${sheet} by=uma grade=B rate=20.00`,
    `RATE_SET sheet=${sheet} by=uma grade=C rate=33.33`,
    `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00 from=2026-03-16 to=2026-03-25`,
    `PERIOD_ADDED sheet=${sheet} by=uma period=2026-02 from=2026-02-01 to=2026-02-28`,
    `PERIOD_ADDED sheet=${sheet} by=uma period=2026-03 from=2026-03-01 to=2026-03-31`,
    `PERIOD_ADDED sheet=${sheet} by=uma period=2026-04 from=2026-04-01 to=2026-04-30`,
    `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=B contact=ada@x`,
    `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
    `PERSON_ADDED sheet=${sheet} by=uma name=Cam grade=A terms=20 contact=ben@x`,
    `ROLLUP sheet=${sheet} by=uma person=Cam claimed=0.00 due-total=0.00 overdue-total=0.00`,
    `PERSON_RETIRED sheet=${sheet} by=uma name=Ada from=2026-03-15`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=clerk-limit value=1.50 from=2026-04-02`,
    `PERIOD_CLOSED sheet=${sheet} by=uma period=2026-04 total=0.00`,
    `PERSON_EDITED sheet=${sheet} by=uma name=Ada grade=B`,
    `PERSON_EDITED sheet=${sheet} by=uma name=Cam grade=B`,
    `PERIOD_CLOSED sheet=${sheet} by=uma period=2026-03 total=0.00`,
    `PERSON_EDITED sheet=${sheet} by=uma name=Cam grade=A`,
    `PERSON_WATCHED sheet=${sheet} by=uma name=Ada`
  ]);
  await ui.clearAsOf(pg_wes);
  await ui.refresh(pg_wes);

